static bool dl_Lb_get(const dl_Lb *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static bool *dl_Lb_at(dl_Lb *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Lb_set(dl_Lb *l, int64_t i, bool v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    bool old = l->items[i];
    l->items[i] = DAN_ID(v);
    DAN_NOREL(old);
    (void)old;
}

static void dl_Lb_write(const dl_Lb *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_bool(l->items[i]);
    }
    putchar(']');
}

static void dl_Lb_insert(dl_Lb *l, int64_t i, bool v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Lb_push(l, v);
    bool last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(bool));
    l->items[i] = last;
}

static void dl_Lb_remove(dl_Lb *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    bool old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(bool));
    l->len--;
    DAN_NOREL(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Lb *dl_Lb_copy(const dl_Lb *l) {
    return dl_Lb_from(l->len, l->items);
}

static inline dl_Lb *dl_Lb_share(dl_Lb *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Lb_release(dl_Lb *l) { if (l) dan_hdr_release(&l->h, dl_Lb_destroy); }
static inline void dl_Lb_give(dl_Lb *l) { if (l) dan_hdr_give(&l->h, dl_Lb_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Lb *dl_Lb_mut(dl_Lb **pp) {
    dl_Lb *l = *pp;
    if (l->h.rc > 1) {
        dl_Lb *r = dl_Lb_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Lb *dl_Lb_reversed(const dl_Lb *l) {
    dl_Lb *r = dl_Lb_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { bool t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Lb *dl_Lb_slice(const dl_Lb *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Lb_from(b - a + 1, l->items + a);
}

static dan_str dl_Lb_str(const dl_Lb *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_bool_to_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Lb_find(const dl_Lb *l, bool b) {
    for (int64_t i = 0; i < l->len; i++) { bool a = l->items[i]; if ((a == b)) return i; }
    return -1;
}
static bool dl_Lb_contains(const dl_Lb *l, bool b) { return dl_Lb_find(l, b) >= 0; }
static bool dl_Lb_eq(const dl_Lb *x, const dl_Lb *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { bool a = x->items[i]; bool b = y->items[i]; if (!((a == b))) return false; }
    return true;
}


