/* ---- list [[дроб]] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LLf { dan_hdr h; int64_t len, cap; dl_Lf* *items; };

static void dl_LLf_destroy(dan_hdr *h) {
    dl_LLf *l = (dl_LLf *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dl_Lf_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LLf *dl_LLf_from(int64_t n, dl_Lf* const *src) {
    dl_LLf *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LLf_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_Lf*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_Lf_share(src[i]);
    return l;
}

static void dl_LLf_push(dl_LLf *l, dl_Lf* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dl_Lf*));
    }
    l->items[l->len++] = dl_Lf_share(v);
}

static dl_Lf* dl_LLf_get(const dl_LLf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dl_Lf* *dl_LLf_at(dl_LLf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LLf_set(dl_LLf *l, int64_t i, dl_Lf* v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Lf* old = l->items[i];
    l->items[i] = dl_Lf_share(v);
    dl_Lf_release(old);
    (void)old;
}

static void dl_LLf_write(const dl_LLf *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dl_Lf_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LLf_insert(dl_LLf *l, int64_t i, dl_Lf* v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LLf_push(l, v);
    dl_Lf* last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dl_Lf*));
    l->items[i] = last;
}

static void dl_LLf_remove(dl_LLf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Lf* old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dl_Lf*));
    l->len--;
    dl_Lf_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LLf *dl_LLf_copy(const dl_LLf *l) {
    return dl_LLf_from(l->len, l->items);
}

static inline dl_LLf *dl_LLf_share(dl_LLf *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LLf_release(dl_LLf *l) { if (l) dan_hdr_release(&l->h, dl_LLf_destroy); }
static inline void dl_LLf_give(dl_LLf *l) { if (l) dan_hdr_give(&l->h, dl_LLf_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LLf *dl_LLf_mut(dl_LLf **pp) {
    dl_LLf *l = *pp;
    if (l->h.rc > 1) {
        dl_LLf *r = dl_LLf_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LLf *dl_LLf_reversed(const dl_LLf *l) {
    dl_LLf *r = dl_LLf_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dl_Lf* t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LLf *dl_LLf_slice(const dl_LLf *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LLf_from(b - a + 1, l->items + a);
}

static dan_str dl_LLf_str(const dl_LLf *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dl_Lf_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LLf_find(const dl_LLf *l, dl_Lf* b) {
    for (int64_t i = 0; i < l->len; i++) { dl_Lf* a = l->items[i]; if (dl_Lf_eq(a, b)) return i; }
    return -1;
}
static bool dl_LLf_contains(const dl_LLf *l, dl_Lf* b) { return dl_LLf_find(l, b) >= 0; }
static bool dl_LLf_eq(const dl_LLf *x, const dl_LLf *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dl_Lf* a = x->items[i]; dl_Lf* b = y->items[i]; if (!(dl_Lf_eq(a, b))) return false; }
    return true;
}


