/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsTproverkau2ePeremennaya_block(dm_DsTproverkau2ePeremennaya *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dt_proverkau2ePeremennaya) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dt_proverkau2ePeremennaya *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsTproverkau2ePeremennaya_reindex(dm_DsTproverkau2ePeremennaya *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsTproverkau2ePeremennaya_lookup(const dm_DsTproverkau2ePeremennaya *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsTproverkau2ePeremennaya_grow(dm_DsTproverkau2ePeremennaya *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dt_proverkau2ePeremennaya *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsTproverkau2ePeremennaya_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsTproverkau2ePeremennaya_reindex(d);
}
static void dm_DsTproverkau2ePeremennaya_put(dm_DsTproverkau2ePeremennaya *d, dan_str k, dt_proverkau2ePeremennaya v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsTproverkau2ePeremennaya_lookup(d, k, h);
    if (e >= 0) { dt_proverkau2ePeremennaya old = d->vals[e]; d->vals[e] = dt_proverkau2ePeremennaya_share(v); dt_proverkau2ePeremennaya_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsTproverkau2ePeremennaya_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dt_proverkau2ePeremennaya_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
