static void dm_DsDss_destroy(dan_hdr *h) {
    dm_DsDss *d = (dm_DsDss *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dm_Dss_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsDss *dm_DsDss_new(void) {
    dm_DsDss *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsDss_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsDss *dm_DsDss_new_detached(void) {
    dm_DsDss *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
